# Let's visualize the different shapes by extracting connected components
from collections import deque

def get_connected_components(grid, start):
    """Get all cells in same color as start, connected orthogonally"""
    grid_color = grid[start[0]][start[1]]
    visited = set()
    queue = deque([start])
    component = []

    while queue:
        r, c = queue.popleft()
        if (r, c) in visited:
            continue
        visited.add((r, c))
        component.append((r, c))

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == grid_color and (nr, nc) not in visited:
                    queue.append((nr, nc))
    return component

# Find all unique colors (not 9 which is background)
background = 9
components = {}
for r in range(len(grid)):
    for c in range(len(grid[0])):
        if grid[r][c] != background:
            comp_key = grid[r][c]
            if comp_key not in components:
                components[comp_key] = get_connected_components(grid, (r, c))
            else:
                # Check if already connected
                existing = components[comp_key]
                new_comp = get_connected_components(grid, (r, c))
